// Shopify sends the whole order as the request body (orders/create webhook).
const o = $json.body ?? $json;
const shop = $json.headers?.['x-shopify-shop-domain'] ?? 'your-store.myshopify.com';
const place = (a) => (a ? [a.city, a.province_code, a.country_code].filter(Boolean).join(', ') : '');
const lines = o.line_items ?? [];

const order = {
  order_id: o.id,
  order: o.name,
  created_at: o.created_at,
  customer: [o.customer?.first_name, o.customer?.last_name].filter(Boolean).join(' '),
  email: o.email ?? o.customer?.email ?? '',
  past_orders: Math.max(0, (o.customer?.orders_count ?? 1) - 1),
  lifetime_spent: Number(o.customer?.total_spent ?? 0),
  total: Number(o.total_price ?? 0),
  currency: o.currency ?? 'USD',
  items: lines.map((li) => `${li.quantity}x ${li.title}`).join('; '),
  item_count: lines.reduce((n, li) => n + (li.quantity ?? 0), 0),
  shipping_method: o.shipping_lines?.[0]?.title ?? '',
  ship_to: place(o.shipping_address),
  bill_to: place(o.billing_address),
  address_mismatch: Boolean(
    o.shipping_address && o.billing_address &&
      (o.shipping_address.province_code !== o.billing_address.province_code ||
        o.shipping_address.country_code !== o.billing_address.country_code),
  ),
  discount_codes: (o.discount_codes ?? []).map((d) => d.code).join(', '),
  note: o.note ?? '',
  admin_url: `https://${shop}/admin/orders/${o.id}`,
};

// The request for the next node (Claude API, structured JSON output).
const ai_request = {
  model: 'claude-opus-5-5',
  max_tokens: 1024,
  output_config: {
    effort: 'low',
    format: {
      type: 'json_schema',
      schema: {
        type: 'object',
        properties: {
          risk: { type: 'string', enum: ['low', 'medium', 'high'] },
          priority: { type: 'string', enum: ['normal', 'rush'] },
          customer_type: { type: 'string', enum: ['new', 'returning', 'vip'] },
          reason: { type: 'string' },
        },
        required: ['risk', 'priority', 'customer_type', 'reason'],
        additionalProperties: false,
      },
    },
  },
  system: [
    'You review new orders for a small online store and classify each one.',
    'risk: "high" when there are two or more warning signs (billing and shipping in different states or countries, a first order of high value or many units, a freight-forwarder address, a note about failed payments or urgency from a new customer); "medium" for one warning sign; otherwise "low".',
    'priority: "rush" when the shipping method is express, overnight or next day, or the note asks for delivery by a date; otherwise "normal".',
    'customer_type: "vip" when past_orders >= 10 or lifetime_spent >= 2000; "returning" when past_orders >= 1; otherwise "new".',
    'reason: one short sentence (max 15 words) a store owner understands, naming the main signal.',
    'Use only the order data you are given.',
  ].join('\n'),
  messages: [{ role: 'user', content: JSON.stringify(order) }],
};

return { json: { ...order, ai_request } };

// The Claude API answer is the first text block: JSON that follows the schema.
const order = $('Clean up order').item.json;
const text = ($json.content ?? []).find((b) => b.type === 'text')?.text;

let ai;
try {
  ai = JSON.parse(text);
} catch (e) {
  // No usable answer (e.g. a refusal or a timeout): send it to a person.
  ai = { risk: 'medium', priority: 'normal', customer_type: 'new', reason: 'AI answer missing; please check this order by hand.' };
}
const needsPerson = ai.risk === 'high' || ai.priority === 'rush' || ai.customer_type === 'vip' || !text;

// Field names match the header row of the "Orders" tab.
return {
  json: {
    Order: order.order,
    Created: order.created_at,
    Customer: order.customer,
    Email: order.email,
    Total: order.total,
    Currency: order.currency,
    Items: order.items,
    'Ship to': order.ship_to,
    'Risk (AI)': ai.risk,
    'Priority (AI)': ai.priority,
    'Customer (AI)': ai.customer_type,
    'Reason (AI)': ai.reason,
    'Needs a person': needsPerson ? 'yes' : 'no',
    'Admin link': order.admin_url,
  },
};

